        [Fact]
        public void Test_OverlappingSegments() {
            var reader = new WKTReader();

            var lineStrings = new LineString[wktLines.Length];
            for (int i = 0; i < wktLines.Length; i++) {
                var lineString = (LineString)reader.Read(wktLines[i]);
                lineStrings[i] = lineString;
            }

        start:
            int count = 0;
            for (int i = 0; i < lineStrings.Length; i++) {
                var boundary1 = lineStrings[i];

                if (i == 62) System.Diagnostics.Debugger.Break();

                for (int j = 0; j < lineStrings.Length; j++) {
                    if (j == i) continue;
                    var boundary2 = lineStrings[j];
                    if (boundary1.Disjoint(boundary2)) continue;

                    if (j == 70) System.Diagnostics.Debugger.Break();

                    if (boundary1.Contains(boundary2)) {
                        count += 1;
                        output.WriteLine($"boundary{i} contains boundary{j}");

                        var geometry = boundary1.SymmetricDifference(boundary2);
                        if (geometry is LineString lineString) {
                            lineStrings[i] = lineString;
                            boundary1 = lineString;
                        }
                        else if (geometry is MultiLineString multiLineString) {
                            lineStrings[i] = (LineString)multiLineString[0];
                            lineStrings = [.. lineStrings, (LineString)multiLineString[1]];
                            goto start;
                        }
                    }
                    else if (boundary1.Intersects(boundary2)) {
                        count += 1;
                        output.WriteLine($"boundary{i} intersects boundary{j}");

                        var geometry = boundary1.Intersection(boundary2);
                        if (geometry is Point point) {
                            if (!(point.EqualsTopologically(boundary2.StartPoint) || point.EqualsTopologically(boundary2.EndPoint))) {
                                ;
                            }
                        }

                        //if (geometry is LineString lineString) {
                        //    lineStrings[i] = lineString;
                        //    boundary1 = lineString;
                        //}
                        //else if (geometry is MultiLineString multiLineString) {
                        //    lineStrings[i] = (LineString)multiLineString[0];
                        //    lineStrings = [.. lineStrings, (LineString)multiLineString[1]];
                        //    goto start;
                        //}
                    }
                }
            }

            using (var target = new Geodatabase(new FileGeodatabaseConnectionPath(new Uri($"file://{IO.Path.GetFullPath(@"s100ed7.gdb")}")))) {
                PersistTopology(target, lineStrings);
            }

            System.Diagnostics.Debugger.Break();
        }

        [Fact]
        private void Test_EdgeGraph() {
            var replicaPath = Environment.GetEnvironmentVariable("S100FrameworkDatabase") ?? throw new System.ArgumentNullException();

            var connection = new FileGeodatabaseConnectionPath(new Uri(IO.Path.GetFullPath(replicaPath)));

            using var geodatabase = new Geodatabase(connection);


            using var surface = geodatabase.OpenDataset<FeatureClass>("surface");

            //var dsnm = "DK40751E";
            var dsnm = "DK40347E";

            using var cursor = surface.Search(new QueryFilter {
                WhereClause = $"upper(ps) = 'S-128' and JSON LIKE '%\"datasetName\":\"{dsnm}\"%'",
            }, true);

            cursor.MoveNext();

            var current = (Feature)cursor.Current;

            var electricProduct = System.Text.Json.JsonSerializer.Deserialize<S100Framework.DomainModel.S128.FeatureTypes.ElectronicProduct>(Convert.ToString(current["json"])!);

            var polygon = (ArcGIS.Core.Geometry.Polygon)current.GetShape();
            var json = polygon.ToJson();

            var shape = GeometryEngine.Instance.ImportFromJson(JsonImportFlags.JsonImportDefaults, json);

            var whereClause = $"upper(ps) = 'S-101' AND usageband = {Convert.ToInt32(current["usageband"])}";

            S100Framework.YAML.Matrix.ParallelOptions = new ParallelOptions {
                MaxDegreeOfParallelism = 1
            };
            S100Framework.YAML.Matrix.Factory = factory;

            var matrix = S100Framework.YAML.Matrix.CreateMatrix((collection) => {
                using (var target = new Geodatabase(new FileGeodatabaseConnectionPath(new Uri($"file://{IO.Path.GetFullPath(@"s100ed7.gdb")}")))) {
                    PersistTopology(target, collection);
                }
            });

            var filterSurfaceTopology = new SpatialQueryFilter {
                WhereClause = $"{whereClause} AND (upper(code) IN ('DEPTHAREA','DREDGEDAREA','LANDAREA','UNSURVEYEDAREA'))",
                //WhereClause = $"{whereClause}",
                FilterGeometry = shape,
                SpatialRelationship = SpatialRelationship.Relation,
                SpatialRelationshipDescription = "T*****FF*",
            };

            var filterSurfaceNavigational = new SpatialQueryFilter {
                WhereClause = $"{whereClause} AND (upper(code) NOT IN ('DEPTHAREA','DREDGEDAREA','LANDAREA','UNSURVEYEDAREA'))",
                //WhereClause = $"{whereClause}",
                FilterGeometry = shape,
                SpatialRelationship = SpatialRelationship.Relation,
                SpatialRelationshipDescription = "T*****FF*",
            };

            var filterCurveTopology = new SpatialQueryFilter {
                WhereClause = $"{whereClause} AND (upper(code) IN ('COASTLINE', 'DEPTHCONTOUR', 'SHORELINECONSTRUCTION'))",
                //WhereClause = $"{whereClause}",
                FilterGeometry = shape,
                SpatialRelationship = SpatialRelationship.Relation,
                SpatialRelationshipDescription = "T*****FF*",
            };

            var filterCurveNavigational = new SpatialQueryFilter {
                WhereClause = $"{whereClause} AND (upper(code) NOT IN ('COASTLINE', 'DEPTHCONTOUR', 'SHORELINECONSTRUCTION','NAVIGATIONLINE','RECOMMENDEDTRACK'))",
                //WhereClause = $"{whereClause}",
                FilterGeometry = shape,
                SpatialRelationship = SpatialRelationship.Relation,
                SpatialRelationshipDescription = "T*****FF*",
            };

            var filterCurveSingleton = new SpatialQueryFilter {
                WhereClause = $"{whereClause} AND (upper(code) IN ('NAVIGATIONLINE','RECOMMENDEDTRACK'))",
                //WhereClause = $"{whereClause}",
                FilterGeometry = shape,
                SpatialRelationship = SpatialRelationship.Relation,
                SpatialRelationshipDescription = "T*****FF*",
            };


            var result = matrix
                .AddTopologyFeatures(LoadSurface(geodatabase, filterSurfaceTopology), LoadCurves(geodatabase, filterCurveTopology))
                .AddNavigationalFeatures(LoadSurface(geodatabase, filterSurfaceNavigational), LoadCurves(geodatabase, filterCurveNavigational))
                .AddSingletonFeatures(LoadCurves(geodatabase, filterCurveSingleton))
                .BuildTopology();

            using (var target = new Geodatabase(new FileGeodatabaseConnectionPath(new Uri($"file://{IO.Path.GetFullPath(@"s100ed7.gdb")}")))) {
                PersistTopology(target, result.Curves);
            }

            var curves = result.Curves.Count();
            var compositeCurves = result.CompositeCurves.Count();
            var surfaces = result.Surfaces.Count();

            this.output.WriteLine($"result: #{curves}, #{compositeCurves}, #{surfaces}");

            System.Diagnostics.Debugger.Break();
        }

        [Fact]
        public void Test_Rounding() {
            var location = new double[2] { 11.123456789, 54.123456789 };

            var yaml = string.Format(CultureInfo.InvariantCulture, "{0:0.0000000},{1:0.0000000}", location[0], location[1]);

            var totext = factory.CreatePoint(new Coordinate(factory.PrecisionModel.MakePrecise(location[0]), factory.PrecisionModel.MakePrecise(location[1]))).ToText().Substring("Point (".Length).Trim(')').Replace(' ', ',');

            System.Diagnostics.Debugger.Break();
        }

