        private static void PersistTopology(Geodatabase geodatabase, S100Framework.YAML.iMatrix result) {
            {
                using var topology = geodatabase.OpenDataset<FeatureClass>("topology");

                topology.DeleteRows(new QueryFilter {
                    WhereClause = "1=1",
                });

                using var buffer = topology.CreateRowBuffer();
                using var cursor = topology.CreateInsertCursor();

                foreach (var c in result.Curves) {
                    buffer["id"] = $"{c.Id}";
                    buffer["shape"] = PolylineBuilderEx.CreatePolyline(c.LineString.Coordinates.Select(e => MapPointBuilderEx.CreateMapPoint(e.X, e.Y, spatialReference)), spatialReference);
                    cursor.Insert(buffer);
                }
                cursor.Flush();
            }
        }

        private static void PersistTopology(Geodatabase geodatabase, IEnumerable<LineString> lineStrings) {
            using var topology = geodatabase.OpenDataset<FeatureClass>("topology");

            topology.DeleteRows(new QueryFilter {
                WhereClause = "1=1",
            });

            using var buffer = topology.CreateRowBuffer();
            using var cursor = topology.CreateInsertCursor();

            int id = 0;
            foreach (var e in lineStrings) {
                buffer["id"] = $"{id++}";
                var text = e.ToText().Substring("LINESTRING (".Length).TrimEnd(')');

                var mapPoints = text.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Select(e => {
                    var location = e.Split(' ');
                    var mapPoint = MapPointBuilderEx.CreateMapPoint(double.Parse(location[0], CultureInfo.InvariantCulture), double.Parse(location[1], CultureInfo.InvariantCulture), spatialReference);
                    if (Math.Round(mapPoint.X, 7) != mapPoint.X || Math.Round(mapPoint.Y, 7) != mapPoint.Y) System.Diagnostics.Debugger.Break();
                    return mapPoint;
                });
                //buffer["shape"] = PolylineBuilderEx.CreatePolyline(e.Coordinates.Select(e => MapPointBuilderEx.CreateMapPoint(e.X, e.Y, spatialReference)), spatialReference);                
                buffer["shape"] = PolylineBuilderEx.CreatePolyline(mapPoints, spatialReference);
                cursor.Insert(buffer);

            }
            cursor.Flush();
        }

        private static void PersistTopology(Geodatabase geodatabase, IEnumerable<S100Framework.YAML.CurveFeature> lineStrings) {
            using var topology = geodatabase.OpenDataset<FeatureClass>("topology");

            topology.DeleteRows(new QueryFilter {
                WhereClause = "1=1",
            });

            using var buffer = topology.CreateRowBuffer();
            using var cursor = topology.CreateInsertCursor();

            int id = 0;
            foreach (var e in lineStrings) {
                buffer["id"] = $"{e.Id}";

                var text = e.LineString.ToText().Substring("LINESTRING (".Length).TrimEnd(')');

                var mapPoints = text.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Select(e => {
                    var location = e.Split(' ');
                    var mapPoint = MapPointBuilderEx.CreateMapPoint(double.Parse(location[0], CultureInfo.InvariantCulture), double.Parse(location[1], CultureInfo.InvariantCulture), spatialReference);
                    if (Math.Round(mapPoint.X, 7) != mapPoint.X || Math.Round(mapPoint.Y, 7) != mapPoint.Y) System.Diagnostics.Debugger.Break();
                    return mapPoint;
                });

                //buffer["shape"] = PolylineBuilderEx.CreatePolyline(e.Coordinates.Select(e => MapPointBuilderEx.CreateMapPoint(e.X, e.Y, spatialReference)), spatialReference);
                buffer["shape"] = PolylineBuilderEx.CreatePolyline(mapPoints, spatialReference);
                cursor.Insert(buffer);

            }
            cursor.Flush();
        }

        private static ICollection<S100Framework.YAML.Polygon> LoadSurface(Geodatabase geodatabase, QueryFilter queryFilter) {
            var polygons = new List<S100Framework.YAML.Polygon>();
            var definitions = geodatabase.GetDefinitions<FeatureClassDefinition>();
            using (var surface = geodatabase.OpenDataset<FeatureClass>(definitions.Single(e => e.GetAliasName().Equals("surface")).GetName())) {
                using var cursor = surface.Search(queryFilter);

                while (cursor.MoveNext()) {
                    var f = (Feature)cursor.Current;

                    var shape = (ArcGIS.Core.Geometry.Polygon)f.GetShape();

                    var name = Convert.ToString(f["name"]);
                    if (string.IsNullOrEmpty(name))
                        name = string.Empty;

                    var exteriorRing = shape.GetExteriorRing(0);
                    var coordinates = exteriorRing.Parts[0].Select(segment => new Coordinate(factory.PrecisionModel.MakePrecise(segment.StartPoint.X), factory.PrecisionModel.MakePrecise(segment.StartPoint.Y))).ToArray();

                    var ex = (LineString)factory.CreateLineString([.. coordinates, coordinates[0]]);
                    ex = ex.RemoveRepeatedVertices();

                    if (shape.PartCount > 1) {
                        var interiorRings = new List<LineString>();

                        foreach (var interiorRing in shape.Parts.Skip(1)) {
                            coordinates = interiorRing.Select(segment => new Coordinate(factory.PrecisionModel.MakePrecise(segment.StartPoint.X), factory.PrecisionModel.MakePrecise(segment.StartPoint.Y))).ToArray();

                            var linestring = (LineString)factory.CreateLineString([.. coordinates, coordinates[0]]);
                            linestring = linestring.RemoveRepeatedVertices();
                            interiorRings.Add(linestring);
                        }

                        polygons.Add(new S100Framework.YAML.Polygon(f.GetObjectID(), name, Convert.ToString(f["code"])!, ex, interiorRings.ToArray()));
                    }
                    else {
                        polygons.Add(new S100Framework.YAML.Polygon(f.GetObjectID(), name, Convert.ToString(f["code"])!, ex, []));
                    }
                }
            }
            return polygons;
        }

        private static ICollection<S100Framework.YAML.Polyline> LoadCurves(Geodatabase geodatabase, QueryFilter queryFilter) {
            var polylines = new List<S100Framework.YAML.Polyline>();
            var definitions = geodatabase.GetDefinitions<FeatureClassDefinition>();
            using (var surface = geodatabase.OpenDataset<FeatureClass>(definitions.Single(e => e.GetAliasName().Equals("curve")).GetName())) {
                using var cursor = surface.Search(queryFilter);

                while (cursor.MoveNext()) {
                    var f = (Feature)cursor.Current;

                    var shape = (ArcGIS.Core.Geometry.Polyline)f.GetShape();

                    var name = Convert.ToString(f["name"]);
                    if (string.IsNullOrEmpty(name))
                        name = string.Empty;

                    var coordinates = shape.Points.Select(segment => new Coordinate(factory.PrecisionModel.MakePrecise(segment.X), factory.PrecisionModel.MakePrecise(segment.Y))).ToArray();

                    var linestring = (LineString)factory.CreateLineString([.. coordinates]);
                    linestring = linestring.RemoveRepeatedVertices();

                    polylines.Add(new S100Framework.YAML.Polyline(f.GetObjectID(), name, Convert.ToString(f["code"])!, linestring));
                }
            }
            return polylines;
        }

